statements:
-- Phase 1: schema only. Critical visit writes stay inaccessible to API roles.
create schema if not exists private;
revoke all on schema private from public, anon, authenticated;

create table public.barbershops (
  id uuid primary key default gen_random_uuid(),
  name text not null check (length(btrim(name)) between 1 and 120),
  currency_code char(3) not null default 'COP' check (currency_code = 'COP'),
  timezone text not null default 'America/Bogota' check (timezone = 'America/Bogota'),
  google_review_url text check (google_review_url is null or google_review_url ~ '^https://[^[:space:]]+$'),
  created_at timestamptz not null default now()
);

create table public.barbershop_users (
  id uuid primary key default gen_random_uuid(),
  barbershop_id uuid not null references public.barbershops(id) on delete restrict,
  user_id uuid not null references auth.users(id) on delete cascade,
  role text not null check (role in ('OWNER', 'BARBER')),
  created_at timestamptz not null default now(),
  unique (barbershop_id, user_id)
);
create index barbershop_users_user_shop_idx on public.barbershop_users(user_id, barbershop_id);

create table public.barbers (
  id uuid primary key default gen_random_uuid(),
  barbershop_id uuid not null references public.barbershops(id) on delete restrict,
  name text not null check (length(btrim(name)) between 1 and 120),
  commission_rate numeric(5,2) not null check (commission_rate between 0 and 100),
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (barbershop_id, id)
);

create table public.services (
  id uuid primary key default gen_random_uuid(),
  barbershop_id uuid not null references public.barbershops(id) on delete restrict,
  name text not null check (length(btrim(name)) between 1 and 120),
  base_price bigint not null check (base_price >= 0),
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (barbershop_id, id)
);

create table public.customers (
  id uuid primary key default gen_random_uuid(),
  barbershop_id uuid not null references public.barbershops(id) on delete restrict,
  name text not null check (length(btrim(name)) between 1 and 120),
  phone text check (phone is null or length(btrim(phone)) between 1 and 30),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (barbershop_id, id)
);
create index customers_shop_name_idx on public.customers(barbershop_id, name);
create index customers_shop_phone_idx on public.customers(barbershop_id, phone) where phone is not null;

create table public.visits (
  id uuid primary key default gen_random_uuid(),
  barbershop_id uuid not null references public.barbershops(id) on delete restrict,
  customer_id uuid,
  barber_id uuid not null,
  payment_method text not null check (payment_method in ('CASH', 'TRANSFER', 'CARD', 'OTHER')),
  subtotal_amount bigint not null check (subtotal_amount >= 0),
  discount_amount bigint not null default 0 check (discount_amount >= 0 and discount_amount <= subtotal_amount),
  total_amount bigint not null check (total_amount >= 0 and total_amount = subtotal_amount - discount_amount),
  commission_rate numeric(5,2) not null check (commission_rate between 0 and 100),
  commission_amount bigint not null check (
    commission_amount >= 0 and commission_amount = round(total_amount::numeric * commission_rate / 100)::bigint
  ),
  status text not null default 'ACTIVE' check (status in ('ACTIVE', 'VOIDED')),
  notes text,
  visited_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  voided_at timestamptz,
  check ((status = 'VOIDED') = (voided_at is not null)),
  unique (barbershop_id, id),
  foreign key (barbershop_id, barber_id) references public.barbers(barbershop_id, id) on delete restrict,
  foreign key (barbershop_id, customer_id) references public.customers(barbershop_id, id) on delete restrict
);
create index visits_shop_date_idx on public.visits(barbershop_id, visited_at desc);
create index visits_shop_customer_date_idx on public.visits(barbershop_id, customer_id, visited_at desc);
create index visits_shop_barber_idx on public.visits(barbershop_id, barber_id);

create table public.visit_items (
  id uuid primary key default gen_random_uuid(),
  barbershop_id uuid not null references public.barbershops(id) on delete restrict,
  visit_id uuid not null,
  service_id uuid not null,
  service_name text not null check (length(btrim(service_name)) between 1 and 120),
  catalog_price bigint not null check (catalog_price >= 0),
  charged_price bigint not null check (charged_price >= 0),
  created_at timestamptz not null default now(),
  foreign key (barbershop_id, visit_id) references public.visits(barbershop_id, id) on delete restrict,
  foreign key (barbershop_id, service_id) references public.services(barbershop_id, id) on delete restrict
);
create index visit_items_shop_visit_idx on public.visit_items(barbershop_id, visit_id);
create index visit_items_shop_service_idx on public.visit_items(barbershop_id, service_id);

create table public.loyalty_programs (
  id uuid primary key default gen_random_uuid(),
  barbershop_id uuid not null unique references public.barbershops(id) on delete restrict,
  required_visits integer not null check (required_visits > 0),
  reward_description text not null check (length(btrim(reward_description)) between 1 and 300),
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create function private.set_updated_at()
returns trigger language plpgsql set search_path = '' as $$
begin
  new.updated_at := clock_timestamp();
  return new;
end;
$$;
revoke all on function private.set_updated_at() from public, anon, authenticated;

do $$
declare table_name text;
begin
  foreach table_name in array array['barbers', 'services', 'customers', 'visits', 'loyalty_programs'] loop
    execute format('create trigger set_updated_at before update on public.%I for each row execute function private.set_updated_at()', table_name);
  end loop;
  foreach table_name in array array['barbershops', 'barbershop_users', 'barbers', 'services', 'customers', 'visits', 'visit_items', 'loyalty_programs'] loop
    execute format('alter table public.%I enable row level security', table_name);
    execute format('revoke all on public.%I from public, anon, authenticated', table_name);
    execute format('grant all on public.%I to service_role', table_name);
  end loop;
end;
$$;

comment on table public.visits is 'No direct API writes. Transactional create/update/void functions are deferred to Phase 3.';

-- The only SECURITY DEFINER helper is a private authorization lookup, not a CRUD RPC.
-- auth.uid() comes from the verified JWT supplied by Supabase's Data API.
create function private.owned_barbershop_ids()
returns setof uuid
language sql stable security definer
set search_path = ''
as $$
  select membership.barbershop_id
  from public.barbershop_users as membership
  where membership.user_id = (select auth.uid())
    and (select auth.uid()) is not null
    and membership.role = 'OWNER';
$$;
revoke all on function private.owned_barbershop_ids() from public, anon, authenticated;
grant usage on schema private to authenticated;
grant execute on function private.owned_barbershop_ids() to authenticated;

grant select on public.barbershops, public.barbershop_users, public.barbers,
  public.services, public.customers, public.visits, public.visit_items,
  public.loyalty_programs to authenticated;

create policy owner_read_shop on public.barbershops
  for select to authenticated
  using (id in (select private.owned_barbershop_ids()));
create policy owner_update_shop on public.barbershops
  for update to authenticated
  using (id in (select private.owned_barbershop_ids()))
  with check (id in (select private.owned_barbershop_ids()));
grant update (name, google_review_url) on public.barbershops to authenticated;

-- No API inserts, updates or deletes for memberships, regardless of role.
create policy owner_read_own_membership on public.barbershop_users
  for select to authenticated
  using (user_id = (select auth.uid()) and role = 'OWNER');

do $$
declare table_name text;
begin
  foreach table_name in array array['barbers', 'services', 'customers', 'loyalty_programs', 'visits', 'visit_items'] loop
    execute format('create policy owner_read on public.%I for select to authenticated using (barbershop_id in (select private.owned_barbershop_ids()))', table_name);
  end loop;
  foreach table_name in array array['barbers', 'services', 'customers', 'loyalty_programs'] loop
    execute format('create policy owner_insert on public.%I for insert to authenticated with check (barbershop_id in (select private.owned_barbershop_ids()))', table_name);
    execute format('create policy owner_update on public.%I for update to authenticated using (barbershop_id in (select private.owned_barbershop_ids())) with check (barbershop_id in (select private.owned_barbershop_ids()))', table_name);
  end loop;
end;
$$;

-- Column grants keep primary keys, tenant ownership and timestamps immutable to API clients.
grant insert (barbershop_id, name, commission_rate, is_active) on public.barbers to authenticated;
grant update (name, commission_rate, is_active) on public.barbers to authenticated;
grant insert (barbershop_id, name, base_price, is_active) on public.services to authenticated;
grant update (name, base_price, is_active) on public.services to authenticated;
grant insert (barbershop_id, name, phone) on public.customers to authenticated;
grant update (name, phone) on public.customers to authenticated;
grant insert (barbershop_id, required_visits, reward_description, is_active) on public.loyalty_programs to authenticated;
grant update (required_visits, reward_description, is_active) on public.loyalty_programs to authenticated;

-- No DELETE grants or policies. visits/visit_items deliberately have SELECT only.

-- Critical visit writes are permitted ONLY through this authorized transaction.
-- The exposed wrapper is invoker; privileged implementation stays in private.
create function private.create_visit(
  p_barber_id uuid,
  p_items jsonb,
  p_discount_amount bigint,
  p_payment_method text,
  p_customer_id uuid default null,
  p_new_customer jsonb default null
) returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_shop uuid;
  v_customer uuid := p_customer_id;
  v_visit uuid;
  v_rate numeric(5,2);
  v_item jsonb;
  v_service public.services%rowtype;
  v_items jsonb := '[]'::jsonb;
  v_seen uuid[] := '{}'::uuid[];
  v_service_id uuid;
  v_price bigint;
  v_subtotal bigint := 0;
  v_total bigint;
  v_name text;
  v_phone text;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  -- Same stable membership choice as the app; clients cannot supply a shop id.
  -- The share lock serializes this operation with membership revocation.
  select m.barbershop_id into v_shop from public.barbershop_users m
    where m.user_id = auth.uid() and m.role = 'OWNER'
    order by m.created_at, m.id limit 1 for share;
  if v_shop is null then raise exception 'OWNER_REQUIRED' using errcode = '42501'; end if;

  if p_payment_method is null or p_payment_method not in ('CASH','TRANSFER','CARD','OTHER') then
    raise exception 'INVALID_PAYMENT' using errcode = '22023';
  end if;
  if p_discount_amount is null or p_discount_amount < 0 or p_discount_amount > 9007199254740991 then
    raise exception 'INVALID_DISCOUNT' using errcode = '22023';
  end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    raise exception 'INVALID_ITEMS' using errcode = '22023';
  end if;
  if jsonb_array_length(p_items) < 1 or jsonb_array_length(p_items) > 100 then
    raise exception 'INVALID_ITEMS' using errcode = '22023';
  end if;
  select b.commission_rate into v_rate from public.barbers b
    where b.id = p_barber_id and b.barbershop_id = v_shop and b.is_active for share;
  if not found then raise exception 'BARBER_UNAVAILABLE' using errcode = '22023'; end if;

  if p_customer_id is not null and p_new_customer is not null then
    raise exception 'INVALID_CUSTOMER' using errcode = '22023';
  end if;
  if p_customer_id is not null then
    perform 1 from public.customers c where c.id = p_customer_id and c.barbershop_id = v_shop for share;
    if not found then raise exception 'CUSTOMER_UNAVAILABLE' using errcode = '22023'; end if;
  end if;
  if p_new_customer is not null then
    if jsonb_typeof(p_new_customer) <> 'object' then raise exception 'INVALID_CUSTOMER' using errcode = '22023'; end if;
    if (p_new_customer - 'name' - 'phone') <> '{}'::jsonb or jsonb_typeof(p_new_customer->'name') is distinct from 'string'
      or (p_new_customer ? 'phone' and jsonb_typeof(p_new_customer->'phone') not in ('string','null')) then
      raise exception 'INVALID_CUSTOMER' using errcode = '22023';
    end if;
    v_name := btrim(p_new_customer->>'name');
    v_phone := nullif(btrim(p_new_customer->>'phone'), '');
    if length(v_name) not between 1 and 120 or length(v_phone) > 30 then
      raise exception 'INVALID_CUSTOMER' using errcode = '22023';
    end if;
    insert into public.customers(barbershop_id,name,phone) values(v_shop,v_name,v_phone) returning id into v_customer;
  end if;

  -- Sort locks deterministically; catalog edits/deactivation wait until commit.
  for v_item in select value from jsonb_array_elements(p_items) order by value->>'service_id' loop
    if jsonb_typeof(v_item) <> 'object' or (v_item - 'service_id' - 'charged_price') <> '{}'::jsonb then
      raise exception 'INVALID_ITEMS' using errcode = '22023';
    end if;
    if (v_item->>'service_id') is null or (v_item->>'service_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or (v_item->>'charged_price') is null or (v_item->>'charged_price') !~ '^[0-9]{1,16}$' then
      raise exception 'INVALID_ITEMS' using errcode = '22023';
    end if;
    v_service_id := (v_item->>'service_id')::uuid;
    v_price := (v_item->>'charged_price')::bigint;
    if v_service_id = any(v_seen) or v_price > 9007199254740991 then
      raise exception 'INVALID_ITEMS' using errcode = '22023';
    end if;
    v_seen := array_append(v_seen,v_service_id);
    select * into v_service from public.services s where s.id = v_service_id and s.barbershop_id = v_shop and s.is_active for share;
    if not found then raise exception 'SERVICE_UNAVAILABLE' using errcode = '22023'; end if;
    v_subtotal := v_subtotal + v_price;
    if v_subtotal > 9007199254740991 then raise exception 'AMOUNT_TOO_LARGE' using errcode = '22023'; end if;
    v_items := v_items || jsonb_build_array(jsonb_build_object('service_id',v_service.id,'service_name',v_service.name,'catalog_price',v_service.base_price,'charged_price',v_price));
  end loop;
  if p_discount_amount > v_subtotal then raise exception 'DISCOUNT_EXCEEDS_SUBTOTAL' using errcode = '22023'; end if;
  v_total := v_subtotal - p_discount_amount;
  insert into public.visits(barbershop_id,customer_id,barber_id,payment_method,subtotal_amount,discount_amount,total_amount,commission_rate,commission_amount,visited_at,notes)
    values(v_shop,v_customer,p_barber_id,p_payment_method,v_subtotal,p_discount_amount,v_total,v_rate,
      round(v_total::numeric * v_rate / 100)::bigint,clock_timestamp(),null)
    returning id into v_visit;
  insert into public.visit_items(barbershop_id,visit_id,service_id,service_name,catalog_price,charged_price)
    select v_shop,v_visit,x.service_id,x.service_name,x.catalog_price,x.charged_price
    from jsonb_to_recordset(v_items) as x(service_id uuid,service_name text,catalog_price bigint,charged_price bigint);
  return v_visit;
end;
$$;
revoke all on function private.create_visit(uuid,jsonb,bigint,text,uuid,jsonb) from public,anon,authenticated;
grant execute on function private.create_visit(uuid,jsonb,bigint,text,uuid,jsonb) to authenticated;

create function public.create_visit(
  p_barber_id uuid,
  p_items jsonb,
  p_discount_amount bigint,
  p_payment_method text,
  p_customer_id uuid default null,
  p_new_customer jsonb default null
) returns uuid
language sql security invoker set search_path = ''
as $$
  select private.create_visit(p_barber_id,p_items,p_discount_amount,p_payment_method,p_customer_id,p_new_customer);
$$;
revoke all on function public.create_visit(uuid,jsonb,bigint,text,uuid,jsonb) from public,anon,authenticated;
grant execute on function public.create_visit(uuid,jsonb,bigint,text,uuid,jsonb) to authenticated;
comment on function public.create_visit(uuid,jsonb,bigint,text,uuid,jsonb) is 'Atomic OWNER visit creation; tenant, snapshots, money and time derived server-side. Returns visit UUID.';
comment on table public.visits is 'No direct API writes. create_visit is the only write path; update/void deferred.';

-- Phase 3B: permanent cancellation, no direct API writes or restoration.
create function private.void_visit(p_visit_id uuid)
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_shop uuid;
  v_visit uuid;
begin
  if v_user is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  -- Same deterministic OWNER selection as requireOwner/create_visit.
  -- Hold membership until commit so revocation cannot interleave.
  select m.barbershop_id into v_shop from public.barbershop_users m
    where m.user_id = v_user and m.role = 'OWNER'
    order by m.created_at, m.id limit 1 for share;
  if v_shop is null then raise exception 'OWNER_REQUIRED' using errcode = '42501'; end if;

  -- Atomic conditional update: concurrent attempts serialize on the row;
  -- only the first can change ACTIVE to VOIDED. Never inspect foreign rows.
  update public.visits
    set status = 'VOIDED', voided_at = clock_timestamp()
    where id = p_visit_id and barbershop_id = v_shop and status = 'ACTIVE'
    returning id into v_visit;
  if v_visit is null then
    -- Identical response for nonexistent, foreign and already voided visits.
    raise exception 'VISIT_UNAVAILABLE' using errcode = '22023';
  end if;
  return v_visit;
end;
$$;
revoke all on function private.void_visit(uuid) from public, anon, authenticated;
grant execute on function private.void_visit(uuid) to authenticated;

create function public.void_visit(p_visit_id uuid)
returns uuid
language sql security invoker set search_path = ''
as $$ select private.void_visit(p_visit_id); $$;
revoke all on function public.void_visit(uuid) from public, anon, authenticated;
grant execute on function public.void_visit(uuid) to authenticated;
comment on function public.void_visit(uuid) is 'OWNER-only permanent cancellation. Tenant and voided_at derived server-side. Returns UUID; missing, foreign and non-ACTIVE visits share VISIT_UNAVAILABLE.';
comment on table public.visits is 'No direct API writes. create_visit and void_visit are the only API write paths. No editing or restoration.';

-- Read-only dashboard. RLS stays active; no privileged aggregate bypass.
create function public.get_dashboard(
  p_period text default 'today', p_start_date date default null, p_end_date date default null
) returns jsonb
language plpgsql stable security invoker set search_path = ''
as $$
declare
  v_shop uuid;
  v_timezone text;
  v_now timestamptz := statement_timestamp();
  v_local timestamp;
  v_start timestamptz;
  v_end timestamptz;
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  select m.barbershop_id, s.timezone into v_shop, v_timezone
    from public.barbershop_users m join public.barbershops s on s.id = m.barbershop_id
    where m.user_id = auth.uid() and m.role = 'OWNER'
    order by m.created_at, m.id limit 1;
  if v_shop is null then raise exception 'OWNER_REQUIRED' using errcode = '42501'; end if;
  v_local := v_now at time zone v_timezone;
  case p_period
    when 'today' then
      v_start := v_local::date::timestamp at time zone v_timezone;
      v_end := (v_local::date + 1)::timestamp at time zone v_timezone;
    when 'week' then
      v_start := date_trunc('week', v_local) at time zone v_timezone;
      v_end := v_now;
    when 'month' then
      v_start := date_trunc('month', v_local) at time zone v_timezone;
      v_end := v_now;
    when 'custom' then
      if p_start_date is null or p_end_date is null or not isfinite(p_start_date) or not isfinite(p_end_date)
        or p_start_date > p_end_date or p_start_date < date '0001-01-01' or p_end_date > date '9999-12-31' then
        raise exception 'INVALID_PERIOD' using errcode = '22023';
      end if;
      v_start := p_start_date::timestamp at time zone v_timezone;
      v_end := (p_end_date + 1)::timestamp at time zone v_timezone;
    else raise exception 'INVALID_PERIOD' using errcode = '22023';
  end case;
  with active_visits as (
    select v.id, v.barber_id, v.payment_method, v.total_amount, v.commission_amount, v.visited_at
    from public.visits v
    where v.barbershop_id = v_shop and v.status = 'ACTIVE'
      and v.visited_at >= v_start and v.visited_at < v_end
  ), payment_totals as (
    select payment_method, sum(total_amount) amount from active_visits group by payment_method
  ), barber_totals as (
    select barber_id, count(*) visits, sum(total_amount) production, sum(commission_amount) commission
    from active_visits group by barber_id
  ), service_totals as (
    select i.service_id, count(*) quantity,
      (array_agg(i.service_name order by v.visited_at desc, v.id desc, i.id desc))[1] historical_name
    from active_visits v join public.visit_items i on i.visit_id = v.id and i.barbershop_id = v_shop
    group by i.service_id
  ), top_services as (
    select t.service_id, coalesce(s.name, t.historical_name) name, t.quantity
    from service_totals t left join public.services s on s.id = t.service_id and s.barbershop_id = v_shop
    order by t.quantity desc, t.service_id limit 5
  )
  select jsonb_build_object(
    'period', p_period, 'timezone', v_timezone, 'start', v_start, 'end', v_end, 'today', v_local::date,
    -- Decimal strings preserve exact COP sums even above JavaScript's safe integer.
    'totals', (select jsonb_build_object('sales',coalesce(sum(total_amount),0)::text,'visits',count(*)::text,
      'commissions',coalesce(sum(commission_amount),0)::text,'shop',coalesce(sum(total_amount-commission_amount),0)::text) from active_visits),
    'payments', coalesce((select jsonb_agg(jsonb_build_object('method',payment_method,'amount',amount::text)
      order by case payment_method when 'CASH' then 1 when 'TRANSFER' then 2 when 'CARD' then 3 else 4 end) from payment_totals),'[]'::jsonb),
    'barbers', coalesce((select jsonb_agg(jsonb_build_object('id',t.barber_id,'name',b.name,'visits',t.visits::text,
      'production',t.production::text,'commission',t.commission::text) order by t.production desc,t.barber_id)
      from barber_totals t join public.barbers b on b.id=t.barber_id and b.barbershop_id=v_shop),'[]'::jsonb),
    'services',coalesce((select jsonb_agg(jsonb_build_object('id',service_id,'name',name,'quantity',quantity::text)
      order by quantity desc,service_id) from top_services),'[]'::jsonb)
  ) into v_result;
  return v_result;
end;
$$;
revoke all on function public.get_dashboard(text,date,date) from public, anon, authenticated;
grant execute on function public.get_dashboard(text,date,date) to authenticated;
comment on function public.get_dashboard(text,date,date) is 'OWNER aggregate read with RLS. Tenant/timezone derived server-side; ACTIVE visits only. Local calendar periods, exclusive upper bound. Exact numeric strings; no persisted metrics.';

-- Derived, non-materialized activity. Aggregate only visits, never visit_items.
create view public.customer_activity with (security_invoker = true) as
select c.id, c.barbershop_id, c.name, c.phone,
  a.total_visits, a.total_spent, a.last_visit
from public.customers c
cross join lateral (
  select count(*)::text as total_visits,
    coalesce(sum(v.total_amount),0)::text as total_spent,
    max(v.visited_at) as last_visit
  from public.visits v
  where v.barbershop_id=c.barbershop_id and v.customer_id=c.id and v.status='ACTIVE'
) a;
revoke all on public.customer_activity from public, anon, authenticated;
grant select on public.customer_activity to authenticated;
comment on view public.customer_activity is 'Read-only live customer summary; underlying OWNER RLS applies. One ACTIVE visit counts once regardless of services. Exact numeric strings; no persisted metrics.';

create function public.search_customers(p_query text default '', p_page integer default 1)
returns jsonb language plpgsql stable security invoker set search_path = '' as $$
declare
  v_shop uuid;
  v_query text := btrim(coalesce(p_query,''));
  v_digits text;
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select m.barbershop_id into v_shop from public.barbershop_users m
    where m.user_id=auth.uid() and m.role='OWNER' order by m.created_at,m.id limit 1;
  if v_shop is null then raise exception 'OWNER_REQUIRED' using errcode='42501'; end if;
  if length(v_query)>120 or p_page is null or p_page<1 or p_page>100000 then
    raise exception 'INVALID_SEARCH' using errcode='22023';
  end if;
  v_digits := regexp_replace(v_query,'[^0-9]','','g');
  with matched as (
    select c.* from public.customer_activity c
    where c.barbershop_id=v_shop and (
      v_query='' or strpos(lower(c.name),lower(v_query))>0
      or (v_digits<>'' and v_query ~ '^[0-9+().[:space:]-]+$'
        and strpos(regexp_replace(coalesce(c.phone,''),'[^0-9]','','g'),v_digits)>0)
    )
  ), page_rows as (
    select * from matched order by last_visit desc nulls last, name, id
    limit 25 offset ((p_page-1)*25)
  )
  select jsonb_build_object(
    'total',(select count(*)::text from matched),
    'customers',coalesce((select jsonb_agg(to_jsonb(p)-'barbershop_id' order by p.last_visit desc nulls last,p.name,p.id) from page_rows p),'[]'::jsonb)
  ) into v_result;
  return v_result;
end;
$$;
revoke all on function public.search_customers(text,integer) from public,anon,authenticated;
grant execute on function public.search_customers(text,integer) to authenticated;
comment on function public.search_customers(text,integer) is 'OWNER-derived tenant, literal name and format-tolerant phone search; ACTIVE activity ordering and bounded 25-row pages. RLS stays active.';

