CREATE OR REPLACE FUNCTION private.create_visit(p_barber_id uuid, p_items jsonb, p_discount_amount bigint, p_payment_method text, p_customer_id uuid DEFAULT NULL::uuid, p_new_customer jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_shop uuid;
  v_customer uuid := p_customer_id;
  v_visit uuid;
  v_rate numeric(5,2);
  v_item jsonb;
  v_service public.services%rowtype;
  v_items jsonb := '[]'::jsonb;
  v_seen uuid[] := '{}'::uuid[];
  v_service_id uuid;
  v_price bigint;
  v_subtotal bigint := 0;
  v_total bigint;
  v_name text;
  v_phone text;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  -- Same stable membership choice as the app; clients cannot supply a shop id.
  -- The share lock serializes this operation with membership revocation.
  select m.barbershop_id into v_shop from public.barbershop_users m
    where m.user_id = auth.uid() and m.role = 'OWNER'
    order by m.created_at, m.id limit 1 for share;
  if v_shop is null then raise exception 'OWNER_REQUIRED' using errcode = '42501'; end if;

  if p_payment_method is null or p_payment_method not in ('CASH','TRANSFER','CARD','OTHER') then
    raise exception 'INVALID_PAYMENT' using errcode = '22023';
  end if;
  if p_discount_amount is null or p_discount_amount < 0 or p_discount_amount > 9007199254740991 then
    raise exception 'INVALID_DISCOUNT' using errcode = '22023';
  end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    raise exception 'INVALID_ITEMS' using errcode = '22023';
  end if;
  if jsonb_array_length(p_items) < 1 or jsonb_array_length(p_items) > 100 then
    raise exception 'INVALID_ITEMS' using errcode = '22023';
  end if;
  select b.commission_rate into v_rate from public.barbers b
    where b.id = p_barber_id and b.barbershop_id = v_shop and b.is_active for share;
  if not found then raise exception 'BARBER_UNAVAILABLE' using errcode = '22023'; end if;

  if p_customer_id is not null and p_new_customer is not null then
    raise exception 'INVALID_CUSTOMER' using errcode = '22023';
  end if;
  if p_customer_id is not null then
    perform 1 from public.customers c where c.id = p_customer_id and c.barbershop_id = v_shop for share;
    if not found then raise exception 'CUSTOMER_UNAVAILABLE' using errcode = '22023'; end if;
  end if;
  if p_new_customer is not null then
    if jsonb_typeof(p_new_customer) <> 'object' then raise exception 'INVALID_CUSTOMER' using errcode = '22023'; end if;
    if (p_new_customer - 'name' - 'phone') <> '{}'::jsonb or jsonb_typeof(p_new_customer->'name') is distinct from 'string'
      or (p_new_customer ? 'phone' and jsonb_typeof(p_new_customer->'phone') not in ('string','null')) then
      raise exception 'INVALID_CUSTOMER' using errcode = '22023';
    end if;
    v_name := btrim(p_new_customer->>'name');
    v_phone := nullif(btrim(p_new_customer->>'phone'), '');
    if length(v_name) not between 1 and 120 or length(v_phone) > 30 then
      raise exception 'INVALID_CUSTOMER' using errcode = '22023';
    end if;
    insert into public.customers(barbershop_id,name,phone) values(v_shop,v_name,v_phone) returning id into v_customer;
  end if;

  -- Sort locks deterministically; catalog edits/deactivation wait until commit.
  for v_item in select value from jsonb_array_elements(p_items) order by value->>'service_id' loop
    if jsonb_typeof(v_item) <> 'object' or (v_item - 'service_id' - 'charged_price') <> '{}'::jsonb then
      raise exception 'INVALID_ITEMS' using errcode = '22023';
    end if;
    if (v_item->>'service_id') is null or (v_item->>'service_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or (v_item->>'charged_price') is null or (v_item->>'charged_price') !~ '^[0-9]{1,16}$' then
      raise exception 'INVALID_ITEMS' using errcode = '22023';
    end if;
    v_service_id := (v_item->>'service_id')::uuid;
    v_price := (v_item->>'charged_price')::bigint;
    if v_service_id = any(v_seen) or v_price > 9007199254740991 then
      raise exception 'INVALID_ITEMS' using errcode = '22023';
    end if;
    v_seen := array_append(v_seen,v_service_id);
    select * into v_service from public.services s where s.id = v_service_id and s.barbershop_id = v_shop and s.is_active for share;
    if not found then raise exception 'SERVICE_UNAVAILABLE' using errcode = '22023'; end if;
    v_subtotal := v_subtotal + v_price;
    if v_subtotal > 9007199254740991 then raise exception 'AMOUNT_TOO_LARGE' using errcode = '22023'; end if;
    v_items := v_items || jsonb_build_array(jsonb_build_object('service_id',v_service.id,'service_name',v_service.name,'catalog_price',v_service.base_price,'charged_price',v_price));
  end loop;
  if p_discount_amount > v_subtotal then raise exception 'DISCOUNT_EXCEEDS_SUBTOTAL' using errcode = '22023'; end if;
  v_total := v_subtotal - p_discount_amount;
  insert into public.visits(barbershop_id,customer_id,barber_id,payment_method,subtotal_amount,discount_amount,total_amount,commission_rate,commission_amount,visited_at,notes)
    values(v_shop,v_customer,p_barber_id,p_payment_method,v_subtotal,p_discount_amount,v_total,v_rate,
      round(v_total::numeric * v_rate / 100)::bigint,clock_timestamp(),null)
    returning id into v_visit;
  insert into public.visit_items(barbershop_id,visit_id,service_id,service_name,catalog_price,charged_price)
    select v_shop,v_visit,x.service_id,x.service_name,x.catalog_price,x.charged_price
    from jsonb_to_recordset(v_items) as x(service_id uuid,service_name text,catalog_price bigint,charged_price bigint);
  return v_visit;
end;
$function$

CREATE OR REPLACE FUNCTION private.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at := clock_timestamp();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.void_visit(p_visit_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
  v_shop uuid;
  v_visit uuid;
begin
  if v_user is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  -- Same deterministic OWNER selection as requireOwner/create_visit.
  -- Hold membership until commit so revocation cannot interleave.
  select m.barbershop_id into v_shop from public.barbershop_users m
    where m.user_id = v_user and m.role = 'OWNER'
    order by m.created_at, m.id limit 1 for share;
  if v_shop is null then raise exception 'OWNER_REQUIRED' using errcode = '42501'; end if;

  -- Atomic conditional update: concurrent attempts serialize on the row;
  -- only the first can change ACTIVE to VOIDED. Never inspect foreign rows.
  update public.visits
    set status = 'VOIDED', voided_at = clock_timestamp()
    where id = p_visit_id and barbershop_id = v_shop and status = 'ACTIVE'
    returning id into v_visit;
  if v_visit is null then
    -- Identical response for nonexistent, foreign and already voided visits.
    raise exception 'VISIT_UNAVAILABLE' using errcode = '22023';
  end if;
  return v_visit;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_dashboard(p_period text DEFAULT 'today'::text, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_shop uuid;
  v_timezone text;
  v_now timestamptz := statement_timestamp();
  v_local timestamp;
  v_start timestamptz;
  v_end timestamptz;
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  select m.barbershop_id, s.timezone into v_shop, v_timezone
    from public.barbershop_users m join public.barbershops s on s.id = m.barbershop_id
    where m.user_id = auth.uid() and m.role = 'OWNER'
    order by m.created_at, m.id limit 1;
  if v_shop is null then raise exception 'OWNER_REQUIRED' using errcode = '42501'; end if;
  v_local := v_now at time zone v_timezone;
  case p_period
    when 'today' then
      v_start := v_local::date::timestamp at time zone v_timezone;
      v_end := (v_local::date + 1)::timestamp at time zone v_timezone;
    when 'week' then
      v_start := date_trunc('week', v_local) at time zone v_timezone;
      v_end := v_now;
    when 'month' then
      v_start := date_trunc('month', v_local) at time zone v_timezone;
      v_end := v_now;
    when 'custom' then
      if p_start_date is null or p_end_date is null or not isfinite(p_start_date) or not isfinite(p_end_date)
        or p_start_date > p_end_date or p_start_date < date '0001-01-01' or p_end_date > date '9999-12-31' then
        raise exception 'INVALID_PERIOD' using errcode = '22023';
      end if;
      v_start := p_start_date::timestamp at time zone v_timezone;
      v_end := (p_end_date + 1)::timestamp at time zone v_timezone;
    else raise exception 'INVALID_PERIOD' using errcode = '22023';
  end case;
  with active_visits as (
    select v.id, v.barber_id, v.payment_method, v.total_amount, v.commission_amount, v.visited_at
    from public.visits v
    where v.barbershop_id = v_shop and v.status = 'ACTIVE'
      and v.visited_at >= v_start and v.visited_at < v_end
  ), payment_totals as (
    select payment_method, sum(total_amount) amount from active_visits group by payment_method
  ), barber_totals as (
    select barber_id, count(*) visits, sum(total_amount) production, sum(commission_amount) commission
    from active_visits group by barber_id
  ), service_totals as (
    select i.service_id, count(*) quantity,
      (array_agg(i.service_name order by v.visited_at desc, v.id desc, i.id desc))[1] historical_name
    from active_visits v join public.visit_items i on i.visit_id = v.id and i.barbershop_id = v_shop
    group by i.service_id
  ), top_services as (
    select t.service_id, coalesce(s.name, t.historical_name) name, t.quantity
    from service_totals t left join public.services s on s.id = t.service_id and s.barbershop_id = v_shop
    order by t.quantity desc, t.service_id limit 5
  )
  select jsonb_build_object(
    'period', p_period, 'timezone', v_timezone, 'start', v_start, 'end', v_end, 'today', v_local::date,
    -- Decimal strings preserve exact COP sums even above JavaScript's safe integer.
    'totals', (select jsonb_build_object('sales',coalesce(sum(total_amount),0)::text,'visits',count(*)::text,
      'commissions',coalesce(sum(commission_amount),0)::text,'shop',coalesce(sum(total_amount-commission_amount),0)::text) from active_visits),
    'payments', coalesce((select jsonb_agg(jsonb_build_object('method',payment_method,'amount',amount::text)
      order by case payment_method when 'CASH' then 1 when 'TRANSFER' then 2 when 'CARD' then 3 else 4 end) from payment_totals),'[]'::jsonb),
    'barbers', coalesce((select jsonb_agg(jsonb_build_object('id',t.barber_id,'name',b.name,'visits',t.visits::text,
      'production',t.production::text,'commission',t.commission::text) order by t.production desc,t.barber_id)
      from barber_totals t join public.barbers b on b.id=t.barber_id and b.barbershop_id=v_shop),'[]'::jsonb),
    'services',coalesce((select jsonb_agg(jsonb_build_object('id',service_id,'name',name,'quantity',quantity::text)
      order by quantity desc,service_id) from top_services),'[]'::jsonb)
  ) into v_result;
  return v_result;
end;
$function$

